@forelse($entries as $entry)<tr><td>{{ \Carbon\Carbon::parse($entry->entry_date)->format('d-m-Y') }}</td><td>{{ $entry->type === 'deposit' ? 'Deposit masuk' : ($entry->type === 'payment' ? 'Pemakaian deposit' : 'Pembalikan #'.$entry->reversal_of) }}<br>{{ $entry->cost_name }} {{ $entry->reference }}<div style="white-space:pre-wrap">{{ $entry->notes }}</div></td><td>{{ trim($entry->nama_cluster.' '.$entry->kode_kavling) ?: '-' }}</td><td class="money">{{ $entry->amount > 0 ? $money($entry->amount) : '-' }}</td><td class="money">{{ $entry->amount < 0 ? $money(-$entry->amount) : '-' }}</td><td class="money">{{ $money($entry->balance) }}</td></tr>@empty<tr><td colspan="6">Belum ada mutasi.</td></tr>@endforelse
</tbody></table>
<h2>Tagihan per Unit</h2><table><thead><tr><th>Tanggal / Referensi</th><th>Unit</th><th>Rincian</th><th>Tagihan</th><th>Terbayar</th><th>Sisa</th><th>Status</th></tr></thead><tbody>
@forelse($bills as $bill)<tr><td>{{ \Carbon\Carbon::parse($bill->bill_date)->format('d-m-Y') }}<br>{{ $bill->reference ?: '#'.$bill->id }}</td><td>{{ trim($bill->nama_cluster.' '.$bill->kode_kavling) }}</td><td>@foreach($bill->item_balances as $item)<div>{{ $item['name'] }}: {{ $money($item['amount']) }}<br><small>Terbayar {{ $money($item['paid']) }}, sisa {{ $money($item['remaining']) }}</small></div>@endforeach<div style="white-space:pre-wrap">{{ $bill->notes }}</div></td><td class="money">{{ $money($bill->amount) }}</td><td class="money">{{ $money($bill->paid) }}</td><td class="money">{{ $bill->cancelled_at ? '-' : $money(max(0,$bill->amount-$bill->paid)) }}</td><td>{{ $bill->cancelled_at ? 'Dibatalkan' : ($bill->paid >= $bill->amount ? 'Lunas' : ($bill->paid > 0 ? 'Sebagian' : 'Belum dibayar')) }}</td></tr>@empty<tr><td colspan="7">Belum ada tagihan.</td></tr>@endforelse
</tbody></table><p><small>Rekap titipan pada notaris. Tidak otomatis mencatat Pengeluaran perusahaan.</small></p>
